import React from 'react';

const Header = () => {
  return (
    <header className="bg-white p-4 flex justify-end items-center h-16 border-b border-gray-200 flex-shrink-0">
      <div className="flex items-center space-x-3">
        <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={1.5}>
          <path strokeLinecap="round" strokeLinejoin="round" d="M13 10V3L4 14h7v7l9-11h-7z" />
        </svg>
        <span className="text-xl font-semibold text-gray-800">Javelin Tracker</span>
      </div>
    </header>
  );
};

export default Header;
